#include <iostream>
#include <vector>
using namespace std;

vector<int> solve(int n, const vector<int>& p, const vector<int>& q) {
    // 记录每个数字在 p 和 q 中的位置（下标从 1 开始）
    vector<int> posP(n + 1), posQ(n + 1);

    for (int i = 0; i < n; i++) {
        posP[p[i]] = i + 1;
        posQ[q[i]] = i + 1;
    }

    vector<int> ans;
    int i = 1, j = 1; // 当前在两个排列中允许选择的最早位置

    // 从大到小扫描，贪心选择当前还能选的最大数字
    for (int x = n; x >= 1; x--) {
        if (posP[x] >= i && posQ[x] >= j) {
            ans.push_back(x);
            // 更新后续可选位置
            i = posP[x] + 1;
            j = posQ[x] + 1;
        }
    }

    return ans;
}

int main() {
    int n;
    cin >> n;

    vector<int> p(n), q(n);
    for (int i = 0; i < n; i++) cin >> p[i];
    for (int i = 0; i < n; i++) cin >> q[i];

    vector<int> ans = solve(n, p, q);

    cout << ans.size() << "\n";
    for (int i = 0; i < (int)ans.size(); i++) {
        if (i) cout << " ";
        cout << ans[i];
    }
    cout << "\n";

    return 0;
}
